cat > "$SP/focus-app.ps1" <<'PSEOF'
# Runs INSIDE session 1: close leftover task consoles, then maximize and
# foreground the app's main frame.
Add-Type @"
using System;using System.Text;using System.Runtime.InteropServices;
public class F {
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWindowsProc cb, IntPtr l);
  public delegate bool EnumWindowsProc(IntPtr h, IntPtr l);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetClassNameW(IntPtr h, StringBuilder s, int m);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
  [DllImport("user32.dll")] public static extern int GetWindowThreadProcessId(IntPtr h, out int pid);
  [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr h, int c);
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr h);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int L,T,R,B; }
}
"@
$orca = (Get-Process -Name "orca-slicer" -ErrorAction SilentlyContinue).Id
$best = [IntPtr]::Zero; $bestArea = 0
$consoles = New-Object System.Collections.ArrayList
$cb = [F+EnumWindowsProc]{ param($h,$l)
    if (-not [F]::IsWindowVisible($h)) { return $true }
    $procId = 0; [F]::GetWindowThreadProcessId($h,[ref]$procId) | Out-Null
    $c = New-Object System.Text.StringBuilder 256
    [F]::GetClassNameW($h,$c,256) | Out-Null
    $cls = $c.ToString()
    if ($cls -eq "ConsoleWindowClass") { $null = $consoles.Add($procId) }
    if ($orca -contains $procId -and $cls -eq "wxWindowNR") {
        $r = New-Object F+RECT; [F]::GetWindowRect($h,[ref]$r) | Out-Null
        $area = ($r.R - $r.L) * ($r.B - $r.T)
        if ($area -gt $bestArea) { $script:bestArea = $area; $script:best = $h }
    }
    return $true
}
[F]::EnumWindows($cb,[IntPtr]::Zero) | Out-Null
foreach ($cp in ($consoles | Select-Object -Unique)) {
    if ($cp -ne $PID) { Stop-Process -Id $cp -Force -ErrorAction SilentlyContinue }
}
if ($script:best -ne [IntPtr]::Zero) {
    [F]::ShowWindow($script:best, 3) | Out-Null   # SW_MAXIMIZE
    [F]::SetForegroundWindow($script:best) | Out-Null
    "maximized hwnd=$($script:best) area=$($script:bestArea)" | Set-Content C:\guitest\focus.txt
} else {
    "no orca main frame found (orca pids: $($orca -join ','))" | Set-Content C:\guitest\focus.txt
}
