$ErrorActionPreference = "Stop"
$ProgressPreference = "SilentlyContinue"
function Log($m) { Write-Host ("[TOOLS {0:HH:mm:ss}] {1}" -f (Get-Date), $m) }
$tools = "C:\tools"; New-Item -ItemType Directory -Path $tools -Force | Out-Null

# --- CMake 4.3.5 (CI pins ~4.3.0; 4.4 is newer than what CI builds with) ------
if (-not (Test-Path "$tools\cmake\bin\cmake.exe")) {
    Log "CMake 4.3.5"
    Invoke-WebRequest "https://github.com/Kitware/CMake/releases/download/v4.3.5/cmake-4.3.5-windows-x86_64.zip" -OutFile "$tools\cmake.zip"
    Expand-Archive "$tools\cmake.zip" -DestinationPath $tools -Force
    Rename-Item "$tools\cmake-4.3.5-windows-x86_64" "$tools\cmake" -Force
}

# --- Ninja 1.13.2 -------------------------------------------------------------
if (-not (Test-Path "$tools\ninja\ninja.exe")) {
    Log "Ninja 1.13.2"
    Invoke-WebRequest "https://github.com/ninja-build/ninja/releases/download/v1.13.2/ninja-win.zip" -OutFile "$tools\ninja.zip"
    Expand-Archive "$tools\ninja.zip" -DestinationPath "$tools\ninja" -Force
}

# --- Git for Windows 2.55.0.5 -------------------------------------------------
if (-not (Test-Path "C:\Program Files\Git\cmd\git.exe")) {
    Log "Git for Windows 2.55.0.5 (silent install)"
    Invoke-WebRequest "https://github.com/git-for-windows/git/releases/download/v2.55.0.windows.5/Git-2.55.0.5-64-bit.exe" -OutFile "$tools\git-setup.exe"
    Start-Process "$tools\git-setup.exe" -ArgumentList "/VERYSILENT","/NORESTART","/NOCANCEL","/SP-","/SUPPRESSMSGBOXES" -Wait
}

# --- Strawberry Perl (portable) - deps build needs perl for OpenSSL -----------
if (-not (Test-Path "$tools\perl\perl\bin\perl.exe")) {
    Log "Strawberry Perl 5.42.3.1 portable"
    Invoke-WebRequest "https://github.com/StrawberryPerl/Perl-Dist-Strawberry/releases/download/SP_54231_64bit/strawberry-perl-5.42.3.1-64bit-portable.zip" -OutFile "$tools\perl.zip"
    Expand-Archive "$tools\perl.zip" -DestinationPath "$tools\perl" -Force
}

# --- Visual Studio 2022 Build Tools (the long pole) --------------------------
$vswhere = "${env:ProgramFiles(x86)}\Microsoft Visual Studio\Installer\vswhere.exe"
$have = if (Test-Path $vswhere) { & $vswhere -products * -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath } else { $null }
if (-not $have) {
    Log "Visual Studio 2022 Build Tools - downloading bootstrapper"
    Invoke-WebRequest "https://aka.ms/vs/17/release/vs_BuildTools.exe" -OutFile "$tools\vs_BuildTools.exe"
    Log "Installing C++ build tools + Windows SDK (this takes a while)"
    $p = Start-Process "$tools\vs_BuildTools.exe" -Wait -PassThru -ArgumentList `
        "--quiet","--wait","--norestart","--nocache",
        "--add","Microsoft.VisualStudio.Workload.VCTools",
        "--add","Microsoft.VisualStudio.Component.VC.Tools.x86.x64",
        "--includeRecommended"
    Log "VS installer exit code: $($p.ExitCode)"
} else {
    Log "VS build tools already present at: $have"
}

# --- PATH ---------------------------------------------------------------------
$machinePath = [Environment]::GetEnvironmentVariable("Path","Machine")
foreach ($d in @("$tools\cmake\bin","$tools\ninja","$tools\perl\perl\bin","C:\Program Files\Git\cmd")) {
    if ($machinePath -notlike "*$d*") { $machinePath = "$machinePath;$d" }
}
[Environment]::SetEnvironmentVariable("Path",$machinePath,"Machine")
Log "PATH updated"

# --- Report -------------------------------------------------------------------
$env:Path = [Environment]::GetEnvironmentVariable("Path","Machine")
foreach ($c in "git","cmake","ninja","perl") {
    $v = try { (& $c --version 2>&1 | Select-Object -First 1) } catch { "MISSING" }
    Log ("{0,-6} {1}" -f $c, $v)
}
if (Test-Path $vswhere) {
    Log "--- vswhere sees ---"
    & $vswhere -products * -format value -property installationPath | ForEach-Object { Log "  $_" }
    & $vswhere -products * -format value -property displayName     | ForEach-Object { Log "  $_" }
    & $vswhere -products * -format value -property installationVersion | ForEach-Object { Log "  version $_" }
}
Log "DONE"
PSEOF
